  `info_mp` longtext COLLATE utf8mb4_unicode_ci,
  `info_empresa` longtext COLLATE utf8mb4_unicode_ci,
  `info_retiro` longtext COLLATE utf8mb4_unicode_ci,
  `info_convenir` longtext COLLATE utf8mb4_unicode_ci,
  `descuento_efectivo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '10',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
