INSERT INTO `novedades` VALUES (2,'media_6a56584126cad.jpeg','Producto','SEG','ALTERNADORES- ARRANQUES. REGULADORES- PLAQUETAS Y TAPAS','<p data-start=\"121\" data-end=\"163\"><strong data-start=\"124\" data-end=\"163\">¡NUEVA LÍNEA SEG AUTOMOTIVE EN BMH!</strong></p>\r\n<p data-start=\"165\" data-end=\"273\">Seguimos ampliando nuestro catálogo para ofrecerte más soluciones, mejor calidad y disponibilidad inmediata.</p>\r\n<p data-start=\"275\" data-end=\"420\">Ahora incorporamos la línea <strong data-start=\"303\" data-end=\"321\">SEG Automotive</strong>, reconocida mundialmente por su innovación y rendimiento en sistemas eléctricos para el automotor.</p>\r\n<p data-start=\"422\" data-end=\"514\">✅ Alternadores<br data-start=\"436\" data-end=\"439\">\r\n✅ Motores de arranque<br data-start=\"460\" data-end=\"463\">\r\n✅ Reguladores de voltaje<br data-start=\"487\" data-end=\"490\">\r\n✅ Plaquetas porta diodos</p>\r\n<p data-start=\"516\" data-end=\"572\">Con la calidad y el respaldo que tus clientes necesitan.</p>',1,'cc','2024-07-25 14:35:23','2026-07-14 19:41:43'),(3,'media_6a4b9191d00a3.png','Producto','CARGADORES PARA VEHICULOS ELECTRICOS E HIBRIDOS ENCHUFABLES','NUEVA LINEA DE CARGADORES EV CYGNUS','<h3 style=\"font-family: Roboto, sans-serif; font-weight: 500; line-height: 1.1; color: rgb(34, 34, 34); margin-top: 20px; margin-bottom: 10px; font-size: 24px;\"><p data-start=\"213\" data-end=\"319\" class=\"PDq2pG_selectionAnchorContainer\">Incorporamos la nueva línea de <strong data-start=\"244\" data-end=\"265\">cargadores CYGNUS</strong> para <strong data-start=\"271\" data-end=\"318\">vehículos eléctricos e híbridos enchufables</strong>.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"321\" data-end=\"538\">✔ Modelos de <strong data-start=\"334\" data-end=\"350\">7 kW y 11 kW</strong><br>\r\n✔ Versiones <strong data-start=\"363\" data-end=\"388\">de pared y portátiles</strong><br>\r\n✔ Soluciones para uso <strong data-start=\"411\" data-end=\"438\">residencial y comercial</strong><br>\r\n✔ <strong data-start=\"441\" data-end=\"466\">Asesoramiento técnico</strong> para elegir el equipo adecuado<br>\r\n✔ <strong data-start=\"500\" data-end=\"538\">Instalación disponible (a cotizar)</strong></p>\r\n<p data-start=\"540\" data-end=\"616\">Consultanos por disponibilidad, compatibilidad con tu vehículo y cotización.</p>\r\n<p data-start=\"618\" data-end=\"684\">💲 <strong data-start=\"621\" data-end=\"684\">Precios expresados en dólares (U$S – Cotización BNA Venta).</strong></p></h3>',1,'bb','2024-07-25 14:35:23','2026-07-06 15:31:12'),(4,'media_6904c994bca90.png','Producto','RODAMIENTOS','LÍNEA NTN','<p>LÍNEA VARIAS Y ALTERNATIVAS DE LA MEJOR CALIDAD</p>',1,'aa','2025-06-06 22:46:16','2025-10-31 17:37:08');
